sys_script_include.script:
var EventUtilsClient = Class.create();
EventUtilsClient.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	getEventDetails: function() {
		var eventId = this.getParameter('sysparm_eventId');
        var result = {};
        var eventGR = new GlideRecord('x_1610843_event_0_event_record');
		eventGR.addQuery('sys_id',eventId);
		eventGR.query();
        while (eventGR.next()) {
            result = {
                name: eventGR.getValue('event_name'),
                date: eventGR.getValue('event_date'),
                location: eventGR.getDisplayValue('location'),
                status: eventGR.getDisplayValue('status'),
				vip: eventGR.getValue('vip')
            };
        }
		return JSON.stringify(result);
	},

    type: 'EventUtilsClient'
});
